SET NAMES utf8mb4;

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'ایمپلنت دندانی',
'<p>ایمپلنت‌های دندانی ریشه‌های مصنوعی‌اند که برای جایگزینی دندان‌های از دست‌رفته از نظر عملکرد و زیبایی در استخوان فک قرار می‌گیرند. تناسب درمان ایمپلنت با ارزیابی هم‌زمان ساختار استخوان، سلامت لثه، وضعیت عمومی سلامت و نیازهای فردی تعیین می‌شود.</p>
<h2>ایمپلنت دندانی چیست؟</h2>
<p>ایمپلنت ریشه‌ای مصنوعی است که به‌گونه‌ای در استخوان فک قرار می‌گیرد که جای ریشهٔ دندان از دست‌رفته را بگیرد. کار آن پشتیبانی پروتزی است که روی آن ساخته می‌شود، از سوی استخوان. روی ایمپلنت می‌توان یک روکش تکی، بریجی که چند دندان را نگه می‌دارد یا پروتزی ثابت برای کل فک قرار داد.</p>
<p>اینکه کدام پروتز مناسب است بر پایهٔ شمار دندان‌های از دست‌رفته، جایگاه فضا، رابطهٔ اکلوژن و انتظار زیبایی تعیین می‌شود. در میان گزینه‌های ماده برای پروتز، <a href="/fa/zirkonyum-dis-kaplama/">روکش زیرکونیا</a> نیز قابل ارزیابی است.</p>
<p><img src="/assets/uploads/images/ts01-tek-dis-implant-kesiti.webp" alt="نمای مقطعی ایمپلنت تک‌دندان درون استخوان فک" loading="lazy"  /></p>
<p><img src="/assets/uploads/images/ts01-implant-ustu-kuron-parcalari.webp" alt="نمای تفکیکی اجزای سازندهٔ روکش روی ایمپلنت" loading="lazy"  /></p>
<h2>برای چه کسانی قابل ارزیابی است؟</h2>
<p>گزینهٔ ایمپلنت می‌تواند برای کسانی مطرح شود که یک یا چند دندان از دست داده‌اند، از پروتز کنونی خود خرسند نیستند یا به‌جای پروتز متحرک به دنبال راه‌حلی ثابت‌اند. تناسب به یک معیار وابسته نیست:</p>
<ul>
<li>شمار دندان‌های از دست‌رفته، جایگاه فضا و وضعیت دندان‌های مجاور</li>
<li>حجم و کیفیت استخوان فک</li>
<li>سلامت لثه و عادت‌های روزانهٔ بهداشت دهان</li>
<li>وضعیت عمومی سلامت، داروهای مصرفی و مصرف سیگار</li>
</ul>
<p>این موارد تنها پس از معاینه و تصویربرداری لازم می‌توانند با هم ارزیابی شوند. برای نگاهی مقایسه‌ای به دیگر گزینه‌های دندان از دست‌رفته می‌توانید به <a href="/fa/implant/">راهنمای درمان ایمپلنت</a> ما نگاه کنید.</p>
<h2>ارزیابی پیش از ایمپلنت</h2>
<p>برنامه‌ریزی تنها اندازه‌گیری فضا نیست. سابقهٔ سلامت، داروهای مصرفی منظم، وضعیت لثه، حجم و کیفیت استخوان، رابطهٔ اکلوژن و مصرف سیگار با هم در نظر گرفته می‌شوند. با روش‌های تصویربرداری لازم، ارتفاع و پهنای استخوان و مجاورت‌های تشریحی بررسی می‌گردد.</p>
<p>برنامه‌ریزی پروتتیک نیز در همین مرحله انجام می‌شود: جایگاه ایمپلنت بر پایهٔ طراحی پروتزی که روی آن خواهد آمد تعیین می‌گردد. در پایان ارزیابی، گزینه‌ها و مراحل تقریبی با شما در میان گذاشته می‌شود؛ پیش از معاینه تعهدی به شمار ایمپلنت، مدت یا نتیجه داده نمی‌شود.</p>
<h2>درمان چگونه پیش می‌رود؟</h2>
<ol>
<li><strong>معاینه و تصویربرداری</strong> — یافته‌های بالینی و ارزیابی رادیوگرافیک.</li>
<li><strong>برنامه‌ریزی</strong> — تعیین جایگاه و شمار ایمپلنت‌ها و طراحی پروتز.</li>
<li><strong>قراردادن ایمپلنت</strong> — مرحلهٔ جراحی زیر بی‌حسی موضعی.</li>
<li><strong>دورهٔ بهبودی</strong> — مدت مورد انتظار برای یکپارچه‌شدن ایمپلنت با استخوان (اسئواینتگریشن).</li>
<li><strong>پروتز</strong> — قالب‌گیری و نصب پروتز.</li>
<li><strong>معاینات</strong> — پیگیری بالینی منظم و در صورت نیاز رادیوگرافیک.</li>
</ol>
<p>مدت مراحل بر پایهٔ وضعیت استخوان، روش به‌کاررفته و نیاز یا نبود نیاز به اقدام افزوده تغییر می‌کند.</p>
<p><img src="/assets/uploads/images/ts01-implant-tedavi-asamalari.webp" alt="چهار مرحلهٔ درمان ایمپلنت دندانی" loading="lazy"  /></p>
<h2>کمبود استخوان</h2>
<p>افزایش حجم استخوان برای هر بیمار لازم نیست. در مواردی که حجم استخوان ناکافی یافت شود، پیوند یا بالابردن کف سینوس مطرح می‌گردد؛ این نیاز پس از تصویربرداری تعیین می‌شود. برای جزئیات این اقدام‌ها و روند کلی جراحی می‌توانید به صفحهٔ <a href="/fa/agiz-cerrahisi-uygulamalari/">اقدامات جراحی دهان</a> نگاه کنید.</p>
<p><img src="/assets/uploads/images/ts01-kemik-hacmi-karsilastirmasi.webp" alt="مقایسهٔ حجم کافی و ناکافی استخوان فک" loading="lazy"  /></p>
<h2>موفقیت بلندمدت</h2>
<p>موفقیت بلندمدت ایمپلنت‌های دندانی از عوامل بسیاری اثر می‌پذیرد: انتخاب درست مورد، برنامه‌ریزی، بهداشت دهان، مصرف سیگار، وضعیت عمومی سلامت، طراحی پروتز و معاینات منظم. بخشی از این عوامل در اختیار دندان‌پزشک و بخشی در اختیار عادت‌های روزانه است؛ از این رو دورهٔ پس از درمان جزء جدانشدنی برنامه‌ریزی است.</p>
<h2>مراقبت پس از ایمپلنت</h2>
<p>توصیه‌هایی که پس از اقدام داده می‌شود فردی‌اند و اجرای آن‌ها مستقیماً بر بهبودی اثر می‌گذارد. چون بافت‌های پیرامون ایمپلنت نیز می‌توانند ملتهب شوند، مسواک‌زدن روزانه، تمیزکردن بین‌دندانی و معاینات منظم نباید نادیده بمانند.</p>
<p>اگر افزایش ورم، دردی که برطرف نمی‌شود، خون‌ریزی لثه، شل‌شدن پروتز یا احساسی متفاوت هنگام گازگرفتن دیدید، توصیه می‌شود نوبت معاینه بگیرید.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>درمان ایمپلنت چقدر طول می‌کشد؟</strong><br>مدت نه با یک اقدام بلکه با مراحل تعیین می‌شود. دورهٔ بهبودی لازم برای یکپارچه‌شدن ایمپلنت با استخوان بر پایهٔ وضعیت استخوان و روش به‌کاررفته تغییر می‌کند. نیاز یا نبود نیاز به اقدام افزوده نیز بر مدت اثر می‌گذارد. مراحل تقریبی پس از معاینه و تصویربرداری ارائه می‌شود؛ تعهدی به مدت ثابت داده نمی‌شود.</p>
<p><strong>آیا برای ایمپلنت محدودیت سنی وجود دارد؟</strong><br>حد بالای سنی وجود ندارد؛ آنچه تعیین‌کننده است نه سن بلکه پشتیبانی استخوان و لثه و وضعیت عمومی سلامت است. در حد پایین انتظار می‌رود رشد فک کامل شده باشد. تناسب با معاینه تعیین می‌شود.</p>
<p><strong>آیا در حین اقدام درد احساس می‌شود؟</strong><br>قراردادن ایمپلنت زیر بی‌حسی موضعی انجام می‌شود و راحتی اقدام هدف است. احساس فشار و لرزش ممکن است باشد. چون تجربهٔ فردی می‌تواند متفاوت باشد، تضمین قطعی بی‌دردی داده نمی‌شود.</p>
<p><strong>سیگار می‌کشم، آیا ایمپلنت ممکن است؟</strong><br>مصرف سیگار از عواملی است که می‌تواند بر بهبودی پیرامون ایمپلنت و نتیجهٔ بلندمدت اثر منفی بگذارد. ممکن است به‌تنهایی مانع قطعی نباشد؛ اما خطر آشکارا با بیمار در میان گذاشته می‌شود و برنامه‌ریزی بر همان پایه انجام می‌گیرد.</p>
<p><strong>دیابت یا بیماری دیگری دارم، آیا مانع است؟</strong><br>بیماری‌های زمینه‌ای به‌تنهایی به معنای مانع نیستند. کنترل‌شده‌بودن آن‌ها، داروهای مصرفی و در صورت نیاز نظر پزشک مربوط ارزیابی می‌شود. برای برخی گروه‌های دارویی ارزیابی افزوده ممکن است لازم باشد.</p>
<p><strong>اگر ایمپلنت نگیرد چه می‌شود؟</strong><br>از دست رفتن ایمپلنت می‌تواند در دورهٔ زودهنگام یا دیرهنگام رخ دهد و علت‌های آن متفاوت است. پس از ارزیابی یافته‌ها، درمان دوباره، انتظار برای بهبودی ناحیه یا گزینه‌های جایگزین مطرح می‌شوند. برای هر مورد مسیر یکسانی دنبال نمی‌شود.</p>
<h2>ارزیابی منطقه‌ای</h2>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، تناسب ایمپلنت با ارزیابی هم‌زمان معاینهٔ بالینی، یافته‌های تصویربرداری و نیازهای پروتتیک تعیین می‌شود. MSc. Dt. Mehmet Taş دانش‌آموختهٔ دانشکدهٔ دندان‌پزشکی دانشگاه استانبول است و کارشناسی ارشد جراحی دهان و ایمپلنتولوژی را در دانشگاه UniCamillus ایتالیا به پایان رسانده است.</p>
<p><a href="/fa/implant/">درمان ایمپلنت</a> · <a href="/fa/agiz-cerrahisi-uygulamalari/">اقدامات جراحی دهان</a> · <a href="/fa/zirkonyum-dis-kaplama/">روکش زیرکونیا</a> · <a href="/fa/iletisim">نوبت و تماس</a></p>',
'گزینه‌های ایمپلنت دندانی در درمان دندان‌های از دست‌رفته؛ دربارهٔ معاینه، ارزیابی استخوان، مراحل درمان و دورهٔ بهبودی اطلاع یابید.',
'ایمپلنت دندانی | MSc. Dt. Mehmet Taş',
'FA' FROM treatments WHERE link = 'dental-implant-tedavisi';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'اقدامات جراحی دهان',
'<p>اقدام‌های جراحی دهان نیازمند ارزیابی بالینی و رادیوگرافیک دندان‌ها، استخوان فک و بافت‌های پیرامون است. روش به‌کاررفته، گسترهٔ اقدام و دورهٔ بهبودی به‌صورت فردی برنامه‌ریزی می‌شود. Dt. Mehmet Taş کارشناسی ارشد خود را در رشتهٔ جراحی دهان و ایمپلنتولوژی در دانشگاه UniCamillus ایتالیا به پایان رسانده است.</p>
<h2>گستره</h2><p>ارزیابی دندان نهفته، کشیدن جراحی دندان، جراحی نوک ریشه، افزایش حجم استخوان، لیفت سینوس و <a href="/fa/dental-implant-tedavisi/">جراحی ایمپلنت</a> ذیل این عنوان ارزیابی می‌شوند. همهٔ این اقدام‌ها در کلینیک ما به‌دست MSc. Dt. Mehmet Taş و تیم او انجام می‌گیرد.</p>
<h2>ارزیابی پیش از اقدام</h2><p>بیماری‌های زمینه‌ای، داروهای مصرفی، حساسیت‌ها و خطر خون‌ریزی پرسیده می‌شود؛ معاینهٔ بالینی همراه با رادیوگرافی پانورامیک یا سه‌بعدی ارزیابی می‌گردد. مجاورت‌های تشریحی (سینوس، کانال عصب) بنیاد برنامه‌ریزی را می‌سازند.</p>
<h2>دندان عقل نهفته</h2><p>درد، عفونت مکرر، آسیب به دندان مجاور، گمان به تشکیل کیست یا نواحی غیرقابل تمیزکردن می‌توانند دلیل کشیدن باشند. هر دندان نهفته کشیده نمی‌شود؛ تصمیم پس از معاینه و تصویربرداری با هم گرفته می‌شود.</p>
<h2>برنامه‌ریزی کشیدن جراحی</h2><p>رویکرد جراحی مناسب بر پایهٔ جایگاه دندان، ساختار ریشه، رابطهٔ آن با استخوان و ساختارهای تشریحی تعیین می‌شود؛ اقدام زیر بی‌حسی موضعی انجام می‌گیرد.</p>
<h2>دورهٔ بهبودی</h2><p>نسخه و توصیه‌های مراقبت توضیح داده می‌شود: فشار با گاز استریل در مدتی که دندان‌پزشک می‌گوید، سرما از بیرون، پرهیز از سیگار و الکل، تغذیهٔ نرم و استراحت در روزهای نخست، محافظت از ناحیه و بهداشت منظم دهان. در یافته‌های غیرعادی باید به کلینیک مراجعه کرد.</p>
<h2>توضیح خطرها</h2><p>ورم، درد، خون‌ریزی، عفونت، محدودیت موقت حرکت و خطرهای وابسته به نزدیکی تشریحی پیش از اقدام به‌صورت فردی توضیح داده می‌شوند.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>آیا هر دندان عقلی باید کشیده شود؟</strong><br>خیر. اگر یافته‌هایی مانند درد، عفونت مکرر، آسیب به دندان مجاور، گمان به کیست یا جایگاه غیرقابل تمیزکردن وجود داشته باشد کشیدن ارزیابی می‌شود. برای دندان‌هایی که شکایتی ایجاد نمی‌کنند و قابل پیگیری‌اند مشاهده ترجیح داده می‌شود.</p>
<p><strong>اقدام چقدر طول می‌کشد و در چند جلسه پایان می‌یابد؟</strong><br>بر پایهٔ جایگاه دندان، ساختار ریشه و رابطهٔ آن با استخوان تغییر می‌کند. بیشتر اقدام‌ها در یک جلسه پایان می‌یابند؛ در موارد گسترده برنامه‌ریزی می‌تواند متفاوت باشد. مدت پس از معاینه و تصویربرداری توضیح داده می‌شود.</p>
<p><strong>آیا پس از آن ورم پدید می‌آید؟</strong><br>ورم، حساسیت و محدودیت در جویدن پس از اقدام جراحی یافته‌هایی مورد انتظارند و معمولاً در روزهای نخست آشکارترند. در درد فزاینده، تب، ورم گسترده یا دشواری بلع و تنفس باید بی‌درنگ مراجعه کرد.</p>
<p><strong>پس از اقدام چه بخورم؟</strong><br>در دورهٔ نخست غذاهای نرم و ولرم که ناحیه را تحت فشار نگذارند ترجیح داده می‌شوند. توصیه می‌شود از غذاهای بسیار داغ، نوشیدن با نی، سیگار و الکل پرهیز شود. توصیه‌های دقیق پس از اقدام به‌صورت فردی داده می‌شود.</p>
<p><strong>داروی رقیق‌کنندهٔ خون مصرف می‌کنم، آیا اقدام ممکن است؟</strong><br>داروهای مصرفی خود را حتماً اعلام کنید. داروهای رقیق‌کنندهٔ خون نباید بدون توصیهٔ پزشک قطع شوند. در موارد لازم با گرفتن نظر پزشک مربوط برنامه‌ریزی می‌شود.</p>
<p><strong>آیا کشیدن بخیه لازم است؟</strong><br>بر پایهٔ نوع نخ به‌کاررفته تغییر می‌کند؛ برخی خودبه‌خود جذب می‌شوند و برخی در نوبت معاینه کشیده می‌شوند. اینکه کدام نوع به کار رفته و زمان معاینه چه هنگام است پس از اقدام اعلام می‌گردد.</p>
<h2>ارزیابی منطقه‌ای</h2>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، نیاز به جراحی دهان با معاینهٔ بالینی و روش‌های تصویربرداری لازم ارزیابی می‌شود.</p>
<p><a href="/fa/cerrahi/">جراحی دهان و فک</a> · <a href="/fa/dental-implant-tedavisi/">ایمپلنت دندانی</a> · <a href="/fa/kanal-tedavisi/">درمان ریشه</a> · <a href="/fa/iletisim">نوبت و تماس</a></p>',
'در دندان عقل نهفته، کشیدن جراحی دندان و افزایش حجم استخوان، معاینه، برنامه‌ریزی و دورهٔ بهبودی را بررسی کنید.',
'اقدامات جراحی دهان | MSc. Dt. Mehmet Taş',
'FA' FROM treatments WHERE link = 'agiz-cerrahisi-uygulamalari';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'طراحی لبخند فردی',
'<p>طراحی لبخند تنها یک اقدام که رنگ یا شکل دندان‌ها را تغییر دهد نیست. روندی فردی از برنامه‌ریزی است که در آن دندان‌ها، لثه‌ها، لب‌ها، نسبت‌های چهره و رابطهٔ اکلوژن با هم ارزیابی می‌شوند.</p>
<h2>طراحی لبخند چیست؟</h2>
<p>در طراحی لبخند انتظارهای زیبایی به‌تنهایی در نظر گرفته نمی‌شوند؛ سلامت دهان، عملکرد جویدن، حفظ بافت دندان و ظاهر طبیعی با هم ارزیابی می‌گردند. هدف رسیدن به نتیجه‌ای هماهنگ با چهره و پایدار است.</p>
<h2>چه ارزیابی می‌شود؟</h2>
<ul>
<li>رنگ، شکل و نسبت‌های دندان</li>
<li>سطوح لثه و رابطهٔ لب و دندان</li>
<li>خط لبخند و نسبت‌های چهره</li>
<li>آرایش دندان‌ها و رابطهٔ اکلوژن</li>
<li>ترمیم‌ها و پروتزهای موجود در دهان</li>
</ul>
<h2>برنامه‌ریزی دیجیتال</h2>
<p>در موارد مناسب، ثبت سه‌بعدی که با اسکنر داخل‌دهانی گرفته می‌شود به روند برنامه‌ریزی و ترمیم کمک می‌کند. برنامه‌ریزی دیجیتال ابزاری پیش‌بینانه است؛ تعهدی مبنی بر یکسان‌بودن دقیق نتیجه ندارد.</p>
<h2>درمان‌های ممکن</h2>
<p>اقدام‌هایی که در پی برنامه مطرح می‌شوند از فردی به فرد دیگر متفاوت‌اند: <a href="/fa/dis-beyazlatma/">سفیدکردن</a>، باندینگ، لمینت، E.max، <a href="/fa/zirkonyum-dis-kaplama/">روکش زیرکونیا</a>، اصلاح لثه، ارزیابی ارتودنسی و جایگزینی دندان‌های از دست‌رفته. اینکه کدام اقدام مناسب است با معاینه تعیین می‌شود.</p>
<h2>روند درمان</h2>
<ol>
<li>معاینه و گفت‌وگو دربارهٔ انتظارها</li>
<li>گرفتن عکس و ثبت‌های دیجیتال</li>
<li>ارزیابی سلامت دهان و اکلوژن</li>
<li>توضیح گزینه‌های جایگزین</li>
<li>پیش‌نمایش در موارد مناسب</li>
<li>اجرا</li>
<li>نوبت‌های معاینه</li>
</ol>
<h2>ظاهر طبیعی</h2>
<p>ظاهر طبیعی با نسبت‌های دندانی هماهنگ با چهره، بافت سطح مناسب، عبور نور و خط لبخند متوازن هدف‌گذاری می‌شود. ظاهر استاندارد واحدی برای همه به کار نمی‌رود.</p>
<h2>تناسب</h2>
<p>اگر پوسیدگی فعال، بیماری لثه یا مشکلی عملکردی وجود داشته باشد، درمان آن‌ها پیش از اقدام‌های زیبایی ممکن است لازم باشد. تناسب با ارزیابی دندان‌ها، لثه‌ها، اکلوژن و سلامت کلی دهان تعیین می‌شود.</p>
<h2>Hollywood Smile</h2>
<p>Hollywood Smile بستهٔ استانداردی نیست؛ عبارتی رایج است که تغییرهای زیبایی آشکارتر را توصیف می‌کند. برای هر فرد اقدام یکسان، طول دندان یکسان و رنگ یکسان به کار نمی‌رود.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>آیا طراحی لبخند یک اقدام است؟</strong><br>خیر. طراحی لبخند روندی از برنامه‌ریزی است؛ در پی آن اقدام‌های گوناگونی مانند سفیدکردن، باندینگ، لمینت، زیرکونیا، اصلاح لثه یا ارزیابی ارتودنسی مطرح می‌شوند. اینکه کدام اقدام مناسب است با معاینه تعیین می‌شود.</p>
<p><strong>آیا تراش دندان‌هایم لازم است؟</strong><br>در هر برنامه‌ای تراش لازم نیست. در برخی موارد گزینه‌های محافظه‌کارانه‌تری مانند سفیدکردن یا باندینگ کافی‌اند. میزان آماده‌سازی بر پایهٔ ساختار کنونی دندان، زمینهٔ رنگ، شکل هدف و مادهٔ انتخاب‌شده تغییر می‌کند.</p>
<p><strong>آیا می‌توانم نتیجه را پیشاپیش ببینم؟</strong><br>در موارد مناسب می‌توان با برنامه‌ریزی دیجیتال و پیش‌نمایش دربارهٔ نتیجهٔ احتمالی تصوری به دست آورد. پیش‌نمایش ابزاری برای برنامه‌ریزی است؛ تعهدی به نتیجهٔ عیناً یکسان نیست.</p>
<p><strong>روند چقدر طول می‌کشد؟</strong><br>بر پایهٔ گسترهٔ برنامه، درمان‌های آماده‌سازی لازم و مرحلهٔ آزمایشگاه تغییر می‌کند. اگر پوسیدگی فعال یا بیماری لثه باشد نخست درمان آن‌ها لازم است و این بر مدت اثر می‌گذارد.</p>
<p><strong>هنگام لبخند لثه‌ام زیاد دیده می‌شود، آیا این هم قابل برنامه‌ریزی است؟</strong><br>سطوح لثه، حرکت لب و طول دندان‌ها بخشی از ارزیابی‌اند. در موارد مناسب اصلاح لثه می‌تواند در برنامه جای گیرد؛ تصمیم بر پایهٔ یافته‌های بالینی و رادیوگرافیک گرفته می‌شود.</p>
<p><strong>آیا نتیجه طبیعی دیده می‌شود؟</strong><br>ظاهر طبیعی با نسبت‌های دندانی هماهنگ با چهره، بافت سطح مناسب، عبور نور و خط لبخند متوازن هدف‌گذاری می‌شود. نتیجه به شرایط فردی بستگی دارد و ظاهر استاندارد واحدی به کار نمی‌رود.</p>
<h2>ارزیابی منطقه‌ای</h2>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، گزینه‌های طراحی لبخند با ارزیابی هم‌زمان سلامت دهان، حفظ بافت دندان، عملکرد جویدن و هدف‌های زیبایی طبیعی تعیین می‌شوند.</p>
<p><a href="/fa/estetik/">دندان‌پزشکی زیبایی</a> · <a href="/fa/zirkonyum-dis-kaplama/">روکش زیرکونیا</a> · <a href="/fa/dis-beyazlatma/">سفیدکردن دندان</a> · <a href="/fa/iletisim">نوبت و تماس</a></p>',
'در طراحی لبخند، دندان، لثه، نسبت‌های چهره و اکلوژن با هم ارزیابی می‌شوند. دربارهٔ برنامه‌ریزی دیجیتال و روند کار اطلاع یابید.',
'طراحی لبخند | برنامه‌ریزی دیجیتال | MSc. Dt. Mehmet Taş',
'FA' FROM treatments WHERE link = 'gulus-tasarimi';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'روکش زیرکونیا',
'<p>روکش‌های زیرکونیا ترمیم‌های سرامیکی‌اند که از نظر استحکام، سازگاری زیستی و ظاهر طبیعی گزینه‌های مختلفی از مواد ارائه می‌کنند. برای هر دندانی مادهٔ یکسان یا روش ساخت یکسان مناسب نیست؛ تصمیم بر پایهٔ معاینهٔ بالینی و نیازهای فردی گرفته می‌شود.</p>
<h2>روکش زیرکونیا چیست؟</h2>
<p>ترمیمی سرامیکی بر پایهٔ زیرکونیاست که بخش دیدنی دندان را در بر می‌گیرد. هدف بازسازی شکل از دست‌رفته، عملکرد جویدن و زیبایی با برنامه‌ریزی فردی است.</p>
<h2>در چه وضعیت‌هایی ارزیابی می‌شود؟</h2>
<ul>
<li>از دست رفتن گستردهٔ بافت و ترمیم‌های بزرگ</li>
<li>دندان‌های شکسته یا ساییده</li>
<li>تغییر رنگ و شکل</li>
<li>نیاز به بریج</li>
<li>نیاز به ترمیم روی <a href="/fa/dental-implant-tedavisi/">ایمپلنت</a></li>
</ul>
<h2>ارزیابی مقدماتی</h2>
<p>سلامت دندان و لثه، بافت باقی‌ماندهٔ دندان، اکلوژن، عادت دندان‌قروچه، انتظار زیبایی و درمان‌های جایگزین با هم ارزیابی می‌شوند. بافت سالم دندان تا جای ممکن حفظ می‌شود؛ روکش به‌عنوان تنها گزینه ارائه نمی‌گردد. گزینه‌هایی مانند باندینگ، اینله/انله، لمینت یا E.max بر پایهٔ وضعیت تناسب توضیح داده می‌شوند.</p>
<h2>گردش کار دیجیتال</h2>
<ol>
<li>معاینه و گرفتن ثبت‌ها</li>
<li>آماده‌سازی لازم</li>
<li>اسکن داخل‌دهانی یا قالب‌گیری</li>
<li>طراحی دیجیتال و پروب</li>
<li>ساخت</li>
<li>بررسی تطابق، اکلوژن و زیبایی</li>
<li>نصب</li>
</ol>
<h2>گزینهٔ مونولیتیک و لایه‌ای</h2>
<p>زیرکونیای مونولیتیک یک‌پارچه ساخته می‌شود و بر استحکام تمرکز دارد. در رویکرد لایه‌ای می‌توان با سرامیک سطحی زیبایی، رنگ، بافت و رفتار نور را بهبود بخشید. انتخاب بر پایهٔ جایگاه دندان و باری که بر آن وارد می‌شود انجام می‌گیرد.</p>
<h2>تفاوت زیرکونیا و E.max</h2>
<p>زیرکونیا گزینه‌های گوناگونی از استحکام و عبور نور ارائه می‌کند؛ دی‌سیلیکات لیتیوم (که با نام E.max شناخته می‌شود) می‌تواند به‌ویژه در نواحی زیبایی برگزیده با عبور نور خود برجسته شود. انتخاب بر پایهٔ جایگاه دندان و شرایط بار انجام می‌گیرد.</p>
<table>
<thead><tr><th>عنوان</th><th>زیرکونیا</th><th>E.max / دی‌سیلیکات لیتیوم</th></tr></thead>
<tbody>
<tr><td>وجه برجسته</td><td>گزینه‌های استحکام و گسترهٔ کاربرد وسیع</td><td>عبور نور بالا و شخصیت‌بخشی زیبایی</td></tr>
<tr><td>یادداشت برنامه‌ریزی</td><td>شامل ناحیهٔ خلفی، بریج و روی ایمپلنت؛ نوع ماده بر پایهٔ نیاز زیبایی انتخاب می‌شود.</td><td>می‌تواند به‌ویژه در ناحیهٔ قدامی برگزیده و ترمیم‌های تک‌دندان ارزیابی شود.</td></tr>
<tr><td>معیار تصمیم</td><td colspan="2">هیچ مادهٔ واحدی برای همه برتر نیست. بافت دندان، جایگاه، نیروی اکلوژن، زمینهٔ رنگ، گسترهٔ ترمیم و هدف زیبایی با هم تعیین‌کننده‌اند.</td></tr>
</tbody>
</table>
<h2>ظاهر طبیعی چگونه برنامه‌ریزی می‌شود؟</h2>
<p>رنگ دندان‌های مجاور، بافت سطح، شفافیت، لبهٔ لثه، نسبت‌های دندان، خط لبخند و ظاهر زیر نور با هم ارزیابی می‌شوند. برای برنامه‌ای زیبایی و یکپارچه می‌توانید به صفحهٔ <a href="/fa/gulus-tasarimi/">طراحی لبخند</a> نیز نگاه کنید.</p>
<h2>مراقبت و معاینات</h2>
<p>مسواک‌زدن روزانه، تمیزکردن بین دندان‌ها، حفظ سلامت لثه و معاینات منظم مستقیماً بر نتیجهٔ بلندمدت اثر می‌گذارند. اگر عادت دندان‌قروچه باشد، پلاک محافظ می‌تواند ارزیابی شود.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>روکش زیرکونیا چقدر دوام می‌آورد؟</strong><br>مدت ثابت یا تضمین کاربرد داده نمی‌شود. انتخاب ماده، آماده‌سازی، اکلوژن، بهداشت دهان، عادت فشردن دندان و معاینات منظم بر نتیجهٔ بلندمدت اثر می‌گذارند.</p>
<p><strong>آیا زیرکونیا طبیعی دیده می‌شود؟</strong><br>با رنگ درست، بافت سطح، ضخامت و شخصیت‌بخشی آزمایشگاهی می‌توان به ظاهر طبیعی نزدیک شد؛ نتیجه به شرایط فردی بستگی دارد.</p>
<p><strong>آیا تراش دندان لازم است؟</strong><br>میزان آماده‌سازی لازم بر پایهٔ ساختار کنونی دندان و ترمیم انتخاب‌شده تغییر می‌کند. گزینه‌های محافظه‌کارانه‌تر در معاینه ارزیابی می‌شوند.</p>
<p><strong>زیرکونیا یا E.max؟</strong><br>این تصمیم تنها بر پایهٔ زیبایی گرفته نمی‌شود. جایگاه دندان، بافت باقی‌مانده، بار اکلوزال، زمینهٔ رنگ و طراحی ترمیم با هم ارزیابی می‌شوند.</p>
<h2>ارزیابی منطقه‌ای</h2>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، تناسب روکش زیرکونیا با ارزیابی هم‌زمان بافت باقی‌ماندهٔ دندان، سلامت لثه، رابطهٔ اکلوژن و انتظارهای زیبایی تعیین می‌شود.</p>
<p><a href="/fa/estetik/">دندان‌پزشکی زیبایی</a> · <a href="/fa/gulus-tasarimi/">طراحی لبخند فردی</a> · <a href="/fa/dental-implant-tedavisi/">ایمپلنت دندانی</a> · <a href="/fa/iletisim">نوبت و تماس</a></p>',
'روکش زیرکونیا در چه وضعیت‌هایی ارزیابی می‌شود؟ برنامه‌ریزی دیجیتال، ظاهر طبیعی، تفاوت با E.max و توصیه‌های مراقبت را بررسی کنید.',
'روکش زیرکونیا | MSc. Dt. Mehmet Taş',
'FA' FROM treatments WHERE link = 'zirkonyum-dis-kaplama';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'درمان ریشه',
'<p>هدف درمان ریشه آن است که دندانی که بافت پالپ آن به‌گونه‌ای برگشت‌ناپذیر آسیب دیده یا عفونی شده، در صورت امکان در دهان نگه داشته شود. تصمیم درمان نه تنها بر پایهٔ درد، بلکه با ارزیابی هم‌زمان معاینه، آزمون‌های پالپ و یافته‌های تصویربرداری گرفته می‌شود.</p>
<p>در کلینیک ما درمان‌های ریشه به‌دست دندان‌پزشک متخصص اندودنتیکس ما <strong>زیر بزرگ‌نمایی با لوپ</strong> انجام می‌شود. تجدید درمان ریشه‌ای که پیش‌تر انجام شده (ری‌تریتمنت) و در صورت نیاز جراحی نوک ریشه (رزکسیون آپیکال) نیز در همین گستره انجام می‌گیرد.</p>
<h2>درمان ریشه چیست؟</h2>
<p>هنگامی که بافت پالپ دندان به‌گونه‌ای برگشت‌ناپذیر آسیب می‌بیند یا عفونی می‌شود، اقدامی است شامل تمیزکردن، شکل‌دهی، ضدعفونی و پرکردن کانال‌های ریشه با مادهٔ مناسب.</p>
<h2>در چه وضعیت‌هایی ارزیابی می‌شود؟</h2>
<p>پوسیدگی عمیق، ضربه، ترک یا شکستگی، التهاب یا نکروز پالپ، نشانه‌های عفونت در بافت‌های نوک ریشه و برخی نیازهای ترمیمی می‌توانند درمان ریشه را مطرح کنند.</p>
<h2>نشانه‌ها چه می‌توانند باشند؟</h2>
<p>درد خودبه‌خودی یا شبانه، حساسیت طولانی به سرد و گرم، درد هنگام جویدن، ورم، تغییر رنگ دندان یا ترشح از لثه ممکن است دیده شود. برخی دندان‌ها هیچ نشانه‌ای نمی‌دهند؛ از این رو معاینهٔ منظم اهمیت دارد.</p>
<h2>تشخیص و برنامه‌ریزی</h2>
<p>سابقهٔ درد، معاینهٔ بالینی، آزمون‌های پالپ، یافته‌های پرکاشن و پالپیشن، ارزیابی لثه و رادیوگرافی‌های لازم با هم تفسیر می‌شوند. بر پایهٔ یک نشانهٔ تنها تصمیم گرفته نمی‌شود.</p>
<p><strong>آگاهی‌رسانی مهم:</strong> آنتی‌بیوتیک جای تمیزکردن مکانیکی کانال ریشهٔ عفونی را نمی‌گیرد. نیاز به دارو در وضعیت‌هایی مانند نشانه‌های سیستمیک یا خطر گسترش، جداگانه به‌دست دندان‌پزشک ارزیابی می‌شود.</p>
<h2>درمان چگونه پیش می‌رود؟</h2>
<ol>
<li>بی‌حسی موضعی و ایزولاسیون</li>
<li>آماده‌سازی حفرهٔ دسترسی</li>
<li>تعیین طول کار و آناتومی کانال</li>
<li>تمیزکردن، شکل‌دهی و شست‌وشو (ایریگیشن)</li>
<li>پرکردن کانال</li>
<li>آب‌بندی تاجی و بررسی</li>
</ol>
<h2>یک جلسه یا بیش از یک جلسه؟</h2>
<p>شمار جلسه‌ها بر پایهٔ وضعیت پالپ، نشانه‌های عفونت، آناتومی کانال، نیاز به درمان دوباره و شرایط بالینی تغییر می‌کند. پیش از معاینه تعهدی به شمار ثابت جلسه داده نمی‌شود.</p>
<h2>تجدید درمان ریشه</h2>
<p>در صورت ادامهٔ نشانه‌ها، نشت، کانالی که از قلم افتاده، پرکردگی ناکافی یا گمان به عفونت تازه، می‌توان با خارج‌کردن پرکردگی پیشین، درمان دوباره را ارزیابی کرد. این اقدام نیز در کلینیک ما به‌دست دندان‌پزشک متخصص اندودنتیکس انجام می‌شود.</p>
<h2>ترمیم رویی و پیگیری</h2>
<p>اینکه روی دندان درمان‌ریشه‌شده ترمیم، انله یا روکش لازم است یا نه، بر پایهٔ بافت باقی‌ماندهٔ دندان، خطر ترک، جایگاه دندان و بار جویدن تعیین می‌شود. پیگیری بالینی و در صورت نیاز رادیوگرافیک انجام می‌گیرد.</p>
<table>
<thead><tr><th>گزینه</th><th>چه زمانی می‌تواند ارزیابی شود؟</th><th>یادداشت برنامه‌ریزی</th></tr></thead>
<tbody>
<tr><td>ترمیم کامپوزیت مستقیم</td><td>بافت سالم کافی و از دست رفتن محدود ماده</td><td>آب‌بندی تاجی و بررسی اکلوژن مهم‌اند.</td></tr>
<tr><td>انله / اورلی</td><td>موارد برگزیده که پوشش کاسپ می‌خواهند اما پوشش کامل محیطی ضروری نیست</td><td>می‌تواند به‌عنوان گزینه‌ای چسبنده که بافت باقی‌مانده را حفظ می‌کند ارزیابی شود.</td></tr>
<tr><td>روکش کامل</td><td>از دست رفتن گستردهٔ ماده، خطر ترک یا شرایط ترمیمی موجود</td><td>برای هر دندان درمان‌ریشه‌شده الزام خودکار نیست. <a href="/fa/zirkonyum-dis-kaplama/">روکش زیرکونیا</a> یکی از گزینه‌هاست.</td></tr>
</tbody>
</table>
<p>نوع ترمیم پس از معاینه و با ارزیابی بافت سالم باقی‌مانده، جایگاه دندان، بار اکلوزال، خطر ترک و شرایط ایزولاسیون به‌صورت فردی انتخاب می‌شود.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>آیا درمان ریشه دردناک است؟</strong><br>با بی‌حسی موضعی راحتی اقدام هدف است؛ سطح التهاب و شرایط فردی می‌توانند بر تجربه اثر بگذارند. تضمین قطعی بی‌دردی داده نمی‌شود.</p>
<p><strong>آیا درد پس از درمان طبیعی است؟</strong><br>در روزهای نخست حساسیت هنگام جویدن ممکن است باشد. در درد فزاینده، ورم آشکار، تب یا دشواری بلع و تنفس باید بی‌درنگ به کلینیک مراجعه کرد.</p>
<p><strong>آیا برای هر دندان درمان‌ریشه‌شده روکش لازم است؟</strong><br>خیر. ترمیم رویی بر پایهٔ بافت باقی‌مانده، گروه دندان، خطر ترک و بار عملکردی می‌تواند ترمیم، انله یا روکش باشد.</p>
<p><strong>اگر درمان ناموفق باشد چه می‌شود؟</strong><br>بر پایهٔ تشخیص، گزینه‌هایی مانند تجدید درمان ریشه، جراحی نوک ریشه یا کشیدن می‌توانند ارزیابی شوند؛ هر گزینه برای هر دندان مناسب نیست.</p>
<h2>ارزیابی منطقه‌ای</h2>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، نیاز به درمان ریشه با ارزیابی هم‌زمان معاینهٔ بالینی، آزمون‌های پالپ و یافته‌های تصویربرداری لازم تعیین می‌شود.</p>
<p><a href="/fa/agiz-dis-sagligi/">سلامت دهان و دندان</a> · <a href="/fa/zirkonyum-dis-kaplama/">روکش زیرکونیا</a> · <a href="/fa/agiz-cerrahisi-uygulamalari/">اقدامات جراحی دهان</a> · <a href="/fa/iletisim">نوبت و تماس</a></p>',
'درمان ریشه در چه وضعیت‌هایی انجام می‌شود؟ نشانه‌ها، تشخیص، مراحل درمان و گزینه‌های ترمیم پس از آن را بررسی کنید.',
'درمان ریشه | مراحل و پس از آن | MSc. Dt. Mehmet Taş',
'FA' FROM treatments WHERE link = 'kanal-tedavisi';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'پوسیدگی دندان و ترمیم کامپوزیت',
'<p>ترمیم کامپوزیت می‌تواند برای جایگزینی بافت دندانی که بر اثر پوسیدگی، شکستگی یا ترمیم پیشین از دست رفته، با مادهٔ چسبندهٔ هم‌رنگ دندان به کار رود. هر تغییر رنگی نیازمند ترمیم نیست؛ تصمیم بر پایهٔ فعالیت ضایعه، عمق آن و امکان تمیزکردن گرفته می‌شود.</p>
<h2>پوسیدگی دندان چیست؟</h2>
<p>پوسیدگی دندان روندی از دست‌دادن مواد معدنی است که در آن بیوفیلم، کربوهیدرات‌های قابل تخمیر، زمان، بزاق و عوامل خطر فردی با هم نقش دارند. ضایعه‌های زودهنگام همیشه حفره‌دار نیستند.</p>
<p><img src="/assets/uploads/images/ts12-curugun-ilerleyisi.webp" alt="طرح مقطعی که پیشروی پوسیدگی به سوی مینا، عاج و پالپ را نشان می‌دهد" loading="lazy"  /></p>
<h2>نشانه‌ها</h2>
<p>حساسیت به سرد، گرم یا شیرین، درد هنگام جویدن، گیرکردن غذا یا تغییر رنگ آشکار ممکن است باشد. اما برخی پوسیدگی‌های بین‌دندانی می‌توانند بدون هیچ نشانه‌ای پیش بروند؛ از این رو معاینهٔ منظم اهمیت دارد.</p>
<h2>ارزیابی بالینی و رادیوگرافیک</h2>
<p>ظاهر سطح و امکان تمیزکردن آن، وجود حفره، دندان‌های مجاور، ترمیم‌های پیشین و نزدیکی به پالپ بررسی می‌شوند. در صورت نیاز رادیوگرافی بایت‌وینگ یا پری‌اپیکال به ارزیابی افزوده می‌گردد.</p>
<p><img src="/assets/uploads/images/ts12-klinik-ve-radyografik-degerlendirme.webp" alt="ارزیابی پوسیدگی با معاینهٔ بالینی و رادیوگرافی با هم" loading="lazy"  /></p>
<h2>برنامهٔ درمان</h2>
<p>در ضایعه‌های زودهنگام بدون حفره، کنترل خطر، فلوراید و پیگیری ممکن است کافی باشد. در ضایعه‌هایی که قابل تمیزکردن نیستند یا از دست رفتن ساختاری ایجاد می‌کنند، درمان ترمیمی محافظه‌کارانه ارزیابی می‌شود. هدف تنها برداشتن بافت تیره نیست؛ کنترل فعالیت پوسیدگی، محافظت از پالپ و حفظ بافت سالم دندان تا جای ممکن است.</p>
<h2>روند ترمیم کامپوزیت</h2>
<ol>
<li>انتخاب رنگ و ایزولاسیون</li>
<li>برداشتن کنترل‌شدهٔ بافت پوسیده</li>
<li>اقدام‌های چسبندگی</li>
<li>قراردادن کامپوزیت به‌صورت لایه‌لایه</li>
<li>بررسی نقطهٔ تماس، آناتومی و اکلوژن</li>
<li>پرداخت و پولیش</li>
</ol>
<p><img src="/assets/uploads/images/ts12-kompozit-dolgu-asamalari.webp" alt="طرح نمادینی که مراحل ترمیم کامپوزیت چسبنده را نشان می‌دهد" loading="lazy"  /></p>
<h2>پوسیدگی عمیق و پالپ</h2>
<p>در نزدیکی پالپ، سابقهٔ درد، آزمون‌های حیات، یافته‌های رادیوگرافیک و بافت باقی‌ماندهٔ دندان با هم ارزیابی می‌شوند. برداشتن انتخابی پوسیدگی، اقدام محافظت از پالپ یا <a href="/fa/kanal-tedavisi/">درمان ریشه</a> در وضعیت‌های مختلف مطرح می‌شوند.</p>
<p><img src="/assets/uploads/images/ts12-dolgu-ve-kanal-kapsam-farki.webp" alt="مقایسه‌ای که تفاوت گسترهٔ ترمیم و درمان ریشه را نشان می‌دهد" loading="lazy"  /></p>
<h2>دورهٔ پس از اقدام</h2>
<p>تا برطرف‌شدن بی‌حسی، تغذیهٔ محتاطانه توصیه می‌شود. حساسیت کوتاه‌مدت ممکن است دیده شود؛ اگر تماس بلند، درد خودبه‌خودی طولانی یا درد هنگام جویدن باشد معاینه انجام می‌گیرد.</p>
<h2>مراقبت و پیگیری</h2>
<p>مسواک‌زدن، تمیزکردن بین دندان‌ها، برنامهٔ تغذیه و فلوراید متناسب با خطر پوسیدگی و معاینات منظم اهمیت دارند. لبهٔ ترمیم، نقطهٔ تماس، سایش، شکستگی و خطر پوسیدگی ثانویه پیگیری می‌شوند.</p>
<h2>گزینه‌های ترمیمی بر پایهٔ از دست رفتن بافت</h2>
<table>
<thead><tr><th>گزینه</th><th>گستره</th><th>یادداشت برنامه‌ریزی</th></tr></thead>
<tbody>
<tr><td>ترمیم کامپوزیت مستقیم</td><td>جایگزینی بافت از دست‌رفته درون دهان با مادهٔ چسبنده</td><td>می‌تواند در از دست رفتن محدود و قابل ایزولهٔ بافت گزینه‌ای محافظه‌کارانه باشد.</td></tr>
<tr><td>اینله / انله</td><td>ترمیم غیرمستقیم ساخت آزمایشگاه یا دیجیتال</td><td>در از دست رفتن گسترده‌تر ماده، بر پایهٔ پشتیبانی دیواره‌ها و کاسپ‌های باقی‌مانده ارزیابی می‌شود.</td></tr>
<tr><td>روکش</td><td>ترمیمی که بخش تاجی دندان را گسترده‌تر می‌پوشاند</td><td>در از دست رفتن گستردهٔ ساختار یا خطر شکستگی مطرح می‌شود؛ برای هر دندان پوسیده لازم نیست. <a href="/fa/zirkonyum-dis-kaplama/">روکش زیرکونیا</a> یکی از گزینه‌هاست.</td></tr>
<tr><td>درمان ریشه و ترمیم</td><td>درمان سامانهٔ کانال اگر پالپ به‌گونه‌ای برگشت‌ناپذیر آسیب دیده یا نکروز شده باشد</td><td>تصمیم نه تنها بر پایهٔ ظاهر پوسیدگی؛ بلکه با نشانه‌ها، آزمون‌ها و یافته‌های رادیوگرافیک گرفته می‌شود.</td></tr>
</tbody>
</table>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>آیا هر پوسیدگی درد ایجاد می‌کند؟</strong><br>خیر. به‌ویژه ضایعه‌های زودهنگام یا بین‌دندانی ممکن است نشانه‌ای ندهند. معاینه و در صورت نیاز رادیوگرافی، ارزیابی‌ای فراهم می‌کند که تنها بر درد تکیه ندارد.</p>
<p><strong>آیا هر ناحیهٔ تیره پوسیدگی است؟</strong><br>خیر. تغییر رنگ می‌تواند ضایعهٔ متوقف‌شده، آناتومی شیار یا اثر ترمیم پیشین باشد. فعالیت، ساختار سطح و یافته‌های تصویربرداری با هم ارزیابی می‌شوند.</p>
<p><strong>آیا حساسیت پس از ترمیم طبیعی است؟</strong><br>حساسیت کوتاه‌مدت ممکن است پدید آید؛ عمق، نزدیکی به پالپ و اکلوژن می‌توانند مؤثر باشند. در درد فزاینده، خودبه‌خودی یا طولانی معاینه لازم است.</p>
<p><strong>ترمیم کامپوزیت چقدر دوام می‌آورد؟</strong><br>مدت ثابت یا تضمین کاربرد داده نمی‌شود. اندازه و جایگاه ترمیم، ایزولاسیون، اکلوژن، عادت فشردن دندان، مراقبت و خطر پوسیدگی بر نتیجه اثر می‌گذارند.</p>
<h2>ارزیابی منطقه‌ای</h2>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، نیاز به درمان پوسیدگی و ترمیم کامپوزیت با ارزیابی هم‌زمان معاینهٔ بالینی، رادیوگرافی‌های لازم، وضعیت پالپ، رابطهٔ اکلوژن و خطر پوسیدگی تعیین می‌شود.</p>
<p><a href="/fa/agiz-dis-sagligi/">سلامت دهان و دندان</a> · <a href="/fa/kanal-tedavisi/">درمان ریشه</a> · <a href="/fa/zirkonyum-dis-kaplama/">روکش زیرکونیا</a> · <a href="/fa/iletisim">نوبت و تماس</a></p>',
'پوسیدگی دندان را چگونه تشخیص دهیم؟ دربارهٔ ارزیابی بالینی و رادیوگرافیک، مراحل ترمیم کامپوزیت و رویکرد در پوسیدگی عمیق اطلاع یابید.',
'پوسیدگی دندان و ترمیم کامپوزیت | MSc. Dt. Mehmet Taş',
'FA' FROM treatments WHERE link = 'dis-curugu-kompozit-dolgu';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'سفیدکردن دندان',
'<p>سفیدکردن دندان اقدامی زیبایی است که می‌کوشد رنگ کنونی بافت طبیعی دندان را به سایه‌ای روشن‌تر ببرد. تغییری که می‌توان به دست آورد فردی است؛ رنگ آغازین، نوع تغییر رنگ، ساختار دندان، پروتکل انتخاب‌شده و پاسخ فردی نتیجه را تعیین می‌کنند. از این رو نمی‌توان پیشاپیش شمار مشخصی از سایه‌ها یا نتیجه‌ای قطعی وعده داد.</p>
<p>سفیدکردن اقدامی نیست که مشکل‌های دهان را بپوشاند. اگر پوسیدگی، ترمیم نشت‌دار، التهاب لثه یا سطح ریشهٔ آشکار وجود داشته باشد، نخست این‌ها برطرف می‌شوند؛ سفیدکردن پس از کامل‌شدن این مراحل مطرح می‌گردد.</p>
<h2>سفیدکردن دندان چیست؟</h2>
<p>اقدامی است که می‌کوشد تغییر رنگ‌های بافت طبیعی دندان را با ارزیابی دندان‌پزشک و پروتکل‌های مناسب بر پایهٔ پراکسید به سایه‌ای روشن‌تر ببرد. مادهٔ سفیدکننده مولکول‌های رنگی درون مینا و عاج را به‌صورت شیمیایی تغییر می‌دهد.</p>
<p>با جرم‌گیری و پولیش یکسان نیست: تمیزکردن رسوب‌ها و لکه‌های سطحی روی دندان را برمی‌دارد؛ سفیدکردن اما می‌کوشد خودِ سایهٔ بافت طبیعی دندان را تغییر دهد. در برخی افراد تنها پس از تمیزکردن و پولیش روشنی آشکاری پدید می‌آید و ممکن است نیازی به سفیدکردن نماند.</p>
<h2>چرا رنگ دندان تغییر می‌کند؟</h2>
<table>
<thead><tr><th>نوع تغییر رنگ</th><th>علت‌های اصلی</th><th>پاسخ به سفیدکردن</th></tr></thead>
<tbody>
<tr><td>بیرونی</td><td>چای، قهوه، شراب قرمز، فرآورده‌های تنباکو، برخی دهان‌شویه‌ها، رسوب‌های سطحی</td><td>معمولاً پاسخ آشکارتری می‌دهد؛ بیشتر اوقات همراه با تمیزکردن و پولیش بررسی می‌شود</td></tr>
<tr><td>درونی</td><td>تغییر عاج وابسته به سن، تغییر رنگ پس از ضربه، اختلالات تکاملی، سابقهٔ برخی داروها</td><td>پاسخ متغیرتر است؛ در برخی موارد سفیدکردن به‌تنهایی کافی نیست</td></tr>
<tr><td>آمیخته</td><td>وجود هم‌زمان موارد بالا</td><td>ترتیب و روش بر پایهٔ یافتهٔ معاینه تعیین می‌شود</td></tr>
</tbody>
</table>
<h2>سفیدکردن چه را تغییر می‌دهد و چه را نه؟</h2>
<p>سفیدکردن تنها بر بافت طبیعی دندان اثر می‌گذارد. <strong>رنگ ترمیم‌ها، روکش‌ها، بریج‌ها، لمینت‌ها و پروتزهای روی ایمپلنت در دهان تغییر نمی‌کند.</strong> این نکته برای کسانی که در ناحیهٔ قدامی ترمیم دیدنی دارند مهم است: هنگامی که دندان‌های طبیعی روشن شوند، ترمیم‌های موجود ممکن است تیره‌تر بمانند و ناهماهنگی رنگ پدید آید.</p>
<p>اگر چنین احتمالی باشد، پیشاپیش در معاینه گفته می‌شود. در برخی افراد پس از نشستن رنگ، تجدید ترمیم‌های دیدنی مطرح می‌شود؛ این موضوعی جدا در برنامه‌ریزی است و در صفحه‌های <a href="/fa/zirkonyum-dis-kaplama/">روکش زیرکونیا</a> و <a href="/fa/gulus-tasarimi/">طراحی لبخند فردی</a> بررسی می‌شود.</p>
<h2>در معاینه چه ارزیابی می‌شود؟</h2>
<ul>
<li>وجود پوسیدگی، ترک، سایش و ترمیم نشت‌دار</li>
<li>سلامت لثه، عمق پاکت و وضعیت تحلیل</li>
<li>سطح ریشهٔ آشکار و حساسیت موجود</li>
<li>وضعیت پالپ و سابقهٔ ضربه</li>
<li>نوع و گستردگی تغییر رنگ</li>
<li>جایگاه ترمیم‌ها، روکش‌ها و لمینت‌های موجود در دهان</li>
<li>رابطهٔ اکلوژن و عادت دندان‌قروچه</li>
<li>وضعیت بارداری و شیردهی و سابقهٔ عمومی سلامت</li>
</ul>
<p>آنچه در کل نخستین معاینه ارزیابی می‌شود را می‌توانید در صفحهٔ <a href="/fa/ilk-dis-muayenesi-tedavi-planlamasi/">نخستین معاینهٔ دندان و برنامه‌ریزی درمان</a> بیابید.</p>
<h2>در چه وضعیت‌هایی به تعویق می‌افتد؟</h2>
<p>اگر پوسیدگی درمان‌نشده، ترمیم نشت‌دار، التهاب فعال لثه یا حساسیت آشکار باشد، سفیدکردن تا برطرف‌شدن این یافته‌ها به تعویق می‌افتد. در دورهٔ بارداری و شیردهی سفیدکردن با هدف زیبایی معمولاً به تعویق می‌افتد. در تغییر رنگ‌های درونی شدید، اختلالات تکاملی مینا یا دهان‌هایی با ترمیم‌های دیدنی فراوان، نتیجهٔ مورد انتظار می‌تواند محدود باشد؛ در این صورت گزینه‌ها و تفاوت‌هایشان در معاینه با هم گفت‌وگو می‌شود.</p>
<h2>چه روش‌هایی وجود دارد؟</h2>
<table>
<thead><tr><th>روش</th><th>چگونه انجام می‌شود</th><th>وجه برجسته</th></tr></thead>
<tbody>
<tr><td>کلینیکی</td><td>مادهٔ سفیدکننده با محافظت از لثه و بافت‌های نرم، زیر نظر دندان‌پزشک و به‌صورت کنترل‌شده به کار می‌رود</td><td>اجرا در کلینیک است؛ دوز و مدت زیر نظر دندان‌پزشک</td></tr>
<tr><td>خانگی زیر نظر دندان‌پزشک</td><td>با قالب‌گیری پلاک فردی ساخته می‌شود؛ میزان ژل، مدت استفادهٔ روزانه و مدت کل را دندان‌پزشک تعیین می‌کند</td><td>گام‌به‌گام‌تر پیش می‌رود؛ به نظم در استفاده وابسته است</td></tr>
<tr><td>ترکیبی</td><td>در موارد مناسب، اجرای کلینیکی با استفادهٔ خانگی به‌صورت برنامه‌ریزی‌شده ترکیب می‌شود</td><td>ترتیب و مدت به‌صورت فردی تعیین می‌گردد</td></tr>
<tr><td>سفیدکردن تک‌دندان</td><td>پروتکلی که از درون دندانی که درمان ریشه شده و تیره گشته اجرا می‌شود</td><td>تنها در موارد مناسب؛ وضعیت دندان جداگانه ارزیابی می‌شود</td></tr>
</tbody>
</table>
<p>انتخاب روش بر پایهٔ نوع تغییر رنگ، وضعیت حساسیت، ترمیم‌های موجود در دهان و نظم روزانهٔ فرد انجام می‌گیرد. هیچ روشی برای هر دهانی برتر نیست.</p>
<h2>روند چگونه پیش می‌رود؟</h2>
<ol>
<li><strong>معاینه و ثبت رنگ.</strong> ارزیابی بالینی انجام می‌شود، در صورت نیاز تصویربرداری خواسته می‌شود و رنگ آغازین ثبت می‌گردد.</li>
<li><strong>آماده‌سازی.</strong> پوسیدگی، ترمیم نشت‌دار و مشکلات لثه در صورت وجود برطرف می‌شوند؛ تمیزکردن و پولیش انجام می‌گیرد.</li>
<li><strong>آگاهی‌رسانی و رضایت.</strong> بازهٔ تغییر مورد انتظار، حساسیت احتمالی، ثابت‌ماندن رنگ ترمیم‌ها و احتمال نیاز به ترمیم رنگ توضیح داده می‌شود.</li>
<li><strong>اجرا.</strong> بر پایهٔ پروتکل انتخاب‌شده در کلینیک، در خانه یا هر دو پیش می‌رود.</li>
<li><strong>معاینه.</strong> پس از نشستن رنگ نتیجه ارزیابی می‌شود؛ نیاز به ترمیم رنگ در همین معاینه تعیین می‌گردد.</li>
</ol>
<h2>حساسیت و اثرهای احتمالی</h2>
<p>پرتکرارترین اثر، حساسیت گذرا به سرد و گرم است. تحریک گذرا در لثه نیز ممکن است دیده شود. این اثرها معمولاً اندکی پس از پایان اجرا فروکش می‌کنند. در کسانی که سابقهٔ حساسیت دارند، دوز، مدت اجرا و فاصلهٔ جلسه‌ها بر همان پایه برنامه‌ریزی می‌شود؛ در صورت نیاز فرآورده‌های پشتیبان افزوده می‌گردد.</p>
<p>اگر حساسیت بیش از انتظار ادامه یابد، فزاینده باشد یا ناحیه‌ای در لثه بهبود نیابد، باید با کلینیک تماس بگیرید. طولانی‌کردن اجرا به تصمیم خود یا افزایش میزان ژل می‌تواند حساسیت را تشدید کند.</p>
<h2>نتیجه چقدر پایدار است؟</h2>
<p>پایداری از فردی به فرد دیگر تغییر می‌کند. نوشیدنی‌های رنگی، مصرف تنباکو، عادت‌های بهداشت دهان و ساختار سطح دندان مستقیماً بر مدت اثر می‌گذارند. در روزهای نخست پس از اجرا توصیه می‌شود نوشیدنی و خوراکی‌های تیره محدود شوند. بازگشت جزئی سایه در گذر زمان عادی است؛ نیاز به ترمیم رنگ در معاینهٔ پیگیری تعیین می‌گردد.</p>
<h2>فرآورده‌های سفیدکنندهٔ بازاری</h2>
<p>نوارها، قلم‌ها و ژل‌های سفیدکننده‌ای که بدون نسخه فروخته می‌شوند، اگر بدون ارزیابی وضعیت دهان به کار روند ممکن است نتیجهٔ مورد انتظار را ندهند. مشکل اصلی می‌تواند از قلم بیفتد: اگر علت تیرگی پوسیدگی، ترمیم نشت‌دار یا تغییر پالپ پس از ضربه باشد، فرآورده‌ای که بر سطح به کار می‌رود آن را درست نمی‌کند و تشخیص را به تأخیر می‌اندازد.</p>
<p>خمیردندان‌های سفیدکنندهٔ ساینده و روش‌های خانگی مانند جوش‌شیرین می‌توانند به‌مرور سطح مینا را بسایند؛ عاج آشکارشده زردتر دیده می‌شود و حساسیت می‌تواند بیشتر شود. اگر فرآورده‌ای را در نظر دارید، پرسیدن دربارهٔ آن در معاینه ایمن‌تر است.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>آیا سفیدکردن دندان به مینا آسیب می‌زند؟</strong><br>در اندیکاسیون مناسب، زیر نظر دندان‌پزشک و با دوز و مدت توصیه‌شده، سفیدکردن اقدامی جاافتاده است. خطر بیشتر با استفادهٔ کنترل‌نشده، دوز بیش از حد و طولانی‌کردن اجرا به تصمیم خود فرد مرتبط است.</p>
<p><strong>چند سایه روشن می‌شود؟</strong><br>شمار را نمی‌توان پیشاپیش گفت. رنگ آغازین، نوع تغییر رنگ، ساختار دندان و پاسخ فردی نتیجه را تعیین می‌کنند. بازهٔ تغییر مورد انتظار در معاینه گفت‌وگو می‌شود.</p>
<p><strong>آیا روکش‌های من هم سفید می‌شوند؟</strong><br>خیر. رنگ ترمیم‌ها، روکش‌ها، بریج‌ها و لمینت‌ها تغییر نمی‌کند. وقتی دندان‌های طبیعی روشن شوند این ترمیم‌ها می‌توانند تیره‌تر بمانند؛ اگر چنین احتمالی باشد پیشاپیش گفته می‌شود.</p>
<p><strong>حساسیت دارم، آیا باز هم ممکن است؟</strong><br>در بیشتر موارد قابل ارزیابی است. نخست علت حساسیت بررسی می‌شود؛ اگر سطح ریشهٔ آشکار، ترک یا پوسیدگی باشد برطرف می‌گردد. پروتکل بر پایهٔ وضعیت حساسیت تنظیم می‌شود.</p>
<p><strong>آیا سفیدکردن جای جرم‌گیری را می‌گیرد؟</strong><br>خیر. این دو اقدام متفاوت‌اند. تمیزکردن رسوب‌های روی سطح دندان را برمی‌دارد؛ سفیدکردن می‌کوشد سایهٔ بافت طبیعی دندان را تغییر دهد.</p>
<p><strong>یک دندانم تیره است، چه می‌توان کرد؟</strong><br>تیره‌شدن یک دندان بیشتر اوقات با سابقهٔ ضربه یا درمان ریشه مرتبط است. پس از ارزیابی حیات دندان و وضعیت نوک ریشه، سفیدکردن درون‌دندانی یا گزینه‌های ترمیمی گفت‌وگو می‌شود. در این زمینه صفحهٔ <a href="/fa/kanal-tedavisi/">درمان ریشه</a> نیز می‌تواند کمک کند.</p>
<p><strong>هر چند وقت می‌توان تکرار کرد؟</strong><br>فاصلهٔ تکرار به‌صورت فردی تعیین می‌شود. چون تکرار پرشتاب می‌تواند حساسیت را افزایش دهد، تصمیم بر پایهٔ یافته‌های معاینهٔ پیگیری گرفته می‌شود.</p>
<h2>ارزیابی منطقه‌ای</h2>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، سفیدکردن دندان پس از ارزیابی هم‌زمان نوع تغییر رنگ، سلامت لثه، ترمیم‌های موجود و وضعیت حساسیت برنامه‌ریزی می‌شود. تغییر مورد انتظار و نیاز به مراقبت پیش از اجرا توضیح داده می‌شود.</p>
